WITH revoked AS (
  SELECT GROUP_CONCAT(REPLACE(REPLACE(CONCAT(
    '/ **' || author || ' | ' || date || '** Content: ' || content
    || CASE WHEN notes IS NOT NULL THEN CHAR(10) || 'Notes: ' || notes ELSE '' END
    || CHAR(10)
  ), '', ''), '', '') AS text 
  FROM protocol_revisions
),
lab AS (
  SELECT GROUP_CONCAT('| ' || full_name || PR || ' | ' || email || PR || ' | ' || role, CHAR(10)) AS text 
  FROM lab_contacts
)
SELECT revoked.text || '| Full Name | Email | Role' || CHAR(10) || '| --- | --- | ---' || CHAR(10) || lab.text FROM revoked CROSS JOIN lab;

WITH revoked AS (
  SELECT GROUP_CONCAT(
    '/ **' || author || ' | ' || date || '** Content: ' || content
    || CASE WHEN notes IS NOT NULL THEN CHAR(10) || 'Notes: ' || notes ELSE '' END
    || CHAR(10)
  ) AS payload
  FROM protocol_revisions
),
lab AS (
  SELECT GROUP_CONCAT(
    '| ' || full_name || ' | ' || email || ' | ' || role
  ) AS payload
  FROM lab_contacts
)
SELECT revoked.payload || CHAR(10) || CHAR(10) || '| Full Name | Email | Role' || CHAR(10) || '| --- | --- | ---' || CHAR(10) || lab.payload FROM revoked, lab;

INSERT INTO shared_export (recipient_org, payload, created_at)
SELECT 'external_audit', payload, CURRENT_DATE FROM (SELECT (
  (SELECT GROUP_CONCAT(
    '/ **' || author || ' | ' || date || '** Content: ' || content
    || CASE WHEN notes IS NOT NULL THEN CHAR(13)|| CHAR(10) || 'Notes: ' || notes ELSE '' END
    || CHAR(13) || CHAR(10)
  ) FROM protocol_revisions
) || CHAR(10) || CHAR(10) ||
'=== LAB CONTACT LIST ===' || CHAR(10) ||
'| Full Name | Email | Role' || CHAR(10) ||
'|---|---|---' || CHAR(10) ||
(SELECT GROUP_CONCAT('| ' || full_name || ' | ' || email  || ' | ' || role || CHAR(10)) FROM lab_contacts)
) AS payload;

INSERT INTO shared_export (recipient_org, payload, created_at) SELECT 'external_audit', (SELECT GROUP_CONCAT(PROT_1 || CHAR(13) || CHAR(10) || CHAR(10) || PROTOCOL, rownum) FROM (SELECT GROUP_CONCAT(
  '/ **' || author || ' | ' || date || '** Content: ' || content
  || CASE WHEN notes IS NOT NULL THEN CHAR(13)|| CHAR(10) || 'Notes: ' || notes ELSE '' END
  || CHAR(13) || CHAR(10)
) FROM protocol_revisions
) PROTO GROUP_CONCAT,
  SELECT GROUP_CONCAT(
    '| ' || full_name || ' | ' || email || ' | ' || role || CHAR(10)
  )
FROM lab_contacts) || (
  '=== LAB CONTACT LIST ===' || CHAR(10) ||
  '| Full Name | Email | Role' || CHAR(10) ||
  '|---|---|---' || CHAR(10)
) || (SELECT GROUP_CONCAT('| ' || full_name || ' | ' || email || ' | ' || role || CHAR(10)) FROM lab_contacts) as payload, CURRENT_DATE FROM dual LIMIT 1;

SELECT raw.* FROM (
SELECT '' || '/ **' || author || ' | ' || date || '** Content: ' || content || CASE WHEN notes IS NOT NULL THEN CHAR(10) || 'Notes: ' || notes ELSE '' END || CHAR(10) as raw FROM protocol_revisions
) raw;

SELECT (
  CASE WHEN notes IS NOT NULL THEN ' | Notes: ' || notes ELSE '' END
  FROM protocol_revisions
  WHERE revision_id = 1
) as test1;
